#include <iostream>
#include <cstring>
using namespace std;

long long memo[100];
long long fib(int n) {
    if (n <= 2) return 1;
    if (memo[n] != -1) return memo[n];
    return memo[n] = fib(n-1) + fib(n-2);
}

int main() {
    memset(memo, -1, sizeof(memo));
    int n;
    cin >> n;
    cout << fib(n) << endl;
    return 0;
}

#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    int n;
    cin >> n;
    int a[1000], dp[1000];
    for (int i = 0; i < n; i++) cin >> a[i];
    int ans = 1;
    for (int i = 0; i < n; i++) {
        dp[i] = 1;
        for (int j = 0; j < i; j++) {
            if (a[j] < a[i]) dp[i] = max(dp[i], dp[j] + 1);
        }
        ans = max(ans, dp[i]);
    }
    cout << ans << endl;
    return 0;
}

