#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    int n;
    cin >> n;
    int a[100], sum[100] = {};
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        sum[i+1] = sum[i] + a[i];
    }
    int dp[100][100] = {};
    for (int len = 2; len <= n; len++) {
        for (int l = 0; l + len <= n; l++) {
            int r = l + len - 1;
            dp[l][r] = 1e9;
            for (int k = l; k < r; k++) {
                dp[l][r] = min(dp[l][r], dp[l][k] + dp[k+1][r] + sum[r+1] - sum[l]);
            }
        }
    }
    cout << dp[0][n-1] << endl;
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

vector<int> children[1000];
int w[1000];
int dp[1000][2];

void dfs(int u) {
    dp[u][0] = 0;
    dp[u][1] = w[u];
    for (int v : children[u]) {
        dfs(v);
        dp[u][0] += max(dp[v][0], dp[v][1]);
        dp[u][1] += dp[v][0];
    }
}

int main() {
    int n;
    cin >> n;
    for (int i = 1; i <= n; i++) cin >> w[i];
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        children[u].push_back(v);
    }
    dfs(1);
    cout << max(dp[1][0], dp[1][1]) << endl;
    return 0;
}

#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    int n;
    cin >> n;
    int dist[20][20];
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            cin >> dist[i][j];
    int dp[1<<20][20];
    fill(&dp[0][0], &dp[0][0] + (1<<20)*20, 1e9);
    dp[1][0] = 0;
    for (int S = 1; S < (1<<n); S++) {
        for (int i = 0; i < n; i++) {
            if (!(S & (1<<i))) continue;
            for (int j = 0; j < n; j++) {
                if (S & (1<<j)) continue;
                dp[S|(1<<j)][j] = min(dp[S|(1<<j)][j], dp[S][i] + dist[i][j]);
            }
        }
    }
    cout << dp[(1<<n)-1][0] << endl;
    return 0;
}

