#include <iostream>
#include <cstring>
using namespace std;

int digit[20];
long long dp[20][2];

long long dfs(int pos, bool tight, bool lead) {
    if (pos == 0) return lead ? 0 : 1;
    if (!tight && !lead && dp[pos][0] != -1) return dp[pos][0];
    int limit = tight ? digit[pos] : 9;
    long long ans = 0;
    for (int d = 0; d <= limit; d++) {
        ans += dfs(pos - 1, tight && (d == limit), lead && (d == 0));
    }
    if (!tight && !lead) dp[pos][0] = ans;
    return ans;
}

int main() {
    long long n;
    cin >> n;
    int len = 0;
    long long tmp = n;
    while (tmp > 0) {
        digit[++len] = tmp % 10;
        tmp /= 10;
    }
    memset(dp, -1, sizeof(dp));
    cout << dfs(len, true, true) << endl;
    return 0;
}

#include <iostream>
using namespace std;

const int MOD = 1000000007;

int main() {
    int m, n;
    cin >> m >> n;
    long long dp[105][105] = {};
    for (int i = 1; i <= m; i++) dp[i][1] = 1;
    for (int j = 1; j <= n; j++) dp[1][j] = 1;
    for (int i = 2; i <= m; i++) {
        for (int j = 2; j <= n; j++) {
            dp[i][j] = (dp[i-1][j] + dp[i][j-1]) % MOD;
        }
    }
    cout << dp[m][n] << endl;
    return 0;
}

