#include <iostream>
#include <deque>
using namespace std;

int main() {
    int n, k;
    cin >> n >> k;
    int a[100005];
    long long dp[100005];
    for (int i = 0; i < n; i++) cin >> a[i];
    deque<int> dq;
    dp[0] = 0;
    dq.push_back(0);
    for (int i = 1; i <= n; i++) {
        while (!dq.empty() && dq.front() < i - k) dq.pop_front();
        dp[i] = dp[dq.front()] + a[i-1];
        while (!dq.empty() && dp[i] <= dp[dq.back()]) dq.pop_back();
        dq.push_back(i);
    }
    cout << dp[n] << endl;
    return 0;
}
